import { customType, timestamp, uuid } from 'drizzle-orm/pg-core';

import { uuidv7 } from '../uuidv7';

/** Case-insensitive text (extension created by migration 0002). */
export const citext = customType<{ data: string }>({
  dataType: () => 'citext',
});

/** Raw bytes; node-postgres maps bytea to Buffer both ways. */
export const bytea = customType<{ data: Buffer; driverData: Buffer }>({
  dataType: () => 'bytea',
});

/**
 * UUIDv7 primary key generated by the application (see `uuidv7`). The column
 * has no database default: raw SQL inserts must pass an id.
 */
export const primaryId = () =>
  uuid('id')
    .primaryKey()
    .$defaultFn(() => uuidv7());

export const createdAt = () => timestamp('created_at', { withTimezone: true }).notNull().defaultNow();
